-- ------------------------------------------------------------- Mineralien
INSERT INTO gey_mineral (code, name, formel, art, hier, ort, text, farbe_hex, reihenfolge) VALUES ('SINTER', 'Kieselsinter (Geyserit)', 'SiO₂ · n H₂O', 'Opal-A, amorph', 'J', 'Hier im Becken: an jedem Kegel, jedem Beckenrand und auf den Terrassen', 'Heißes Grundwasser löst Kieselsäure aus dem Rhyolith. Kühlt es an der Oberfläche ab, fällt sie aus: Sinter, als perlige Krusten Geyserit genannt. Frisch ist er nicht kristallin (Opal-A) und zu rund einem Zehntel Wasser. Mit der Zeit reift er über Opal-CT zu Quarz und verliert das Wasser fast ganz. Die bunten Bakterienmatten wachsen mit ein und können bis zur Hälfte des Volumens ausmachen.', '#D6D2C4', 1)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'SINTER'), 14, 1.0000, 'N', 1)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'SINTER'), 8, 2.3706, 'N', 2)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'SINTER'), 1, 0.7411, 'N', 3)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'SINTER'), 33, NULL, 'J', 4)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'SINTER'), 51, NULL, 'J', 5)
/
INSERT INTO gey_mineral (code, name, formel, art, hier, ort, text, farbe_hex, reihenfolge) VALUES ('TRAVERTIN', 'Travertin', 'CaCO₃', 'Calcit und Aragonit', 'N', 'Nicht in diesen Becken: Mammoth Hot Springs im Norden des Parks', 'Bei Mammoth fließt das heiße Wasser durch Kalkstein und nimmt Calcium und Carbonat auf. Tritt es aus, entweicht Kohlendioxid wie aus einer geöffneten Flasche, und Calciumcarbonat fällt aus. So wachsen die Terrassen, viel schneller als Sinter.', '#E8DEC8', 2)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'TRAVERTIN'), 20, 1.0000, 'N', 1)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'TRAVERTIN'), 6, 1.0000, 'N', 2)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'TRAVERTIN'), 8, 3.0000, 'N', 3)
/
INSERT INTO gey_mineral (code, name, formel, art, hier, ort, text, farbe_hex, reihenfolge) VALUES ('SCHWEFEL', 'Schwefel', 'S₈', 'gediegen, elementar', 'N', 'Nicht in diesen Becken: saure Quellen etwa im Norris Geyser Basin', 'In sauren Quellen oxidiert Schwefelwasserstoff. Nahe am Quellmund setzt sich gelber elementarer Schwefel ab, weiter abwärts folgen die rostfarbenen Eisenoxide.', '#ECCE3C', 3)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'SCHWEFEL'), 16, 8.0000, 'N', 1)
/
INSERT INTO gey_mineral (code, name, formel, art, hier, ort, text, farbe_hex, reihenfolge) VALUES ('EISENOXID', 'Eisen(III)-oxid', 'FeO(OH)', 'amorph, vereinfacht als Oxyhydroxid', 'N', 'Nicht in diesen Becken: Matten in sauren Quellen, etwa im Norris Geyser Basin', 'Mikroben oxidieren gelöstes Eisen(II). Das Eisen(III) fällt als weiche, rostrote Matte aus und bindet Arsen. Die Formel ist vereinfacht: In den Matten ist das Oxid meist amorph.', '#B05226', 4)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'EISENOXID'), 26, 1.0000, 'N', 1)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'EISENOXID'), 8, 2.0000, 'N', 2)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'EISENOXID'), 1, 1.0000, 'N', 3)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'EISENOXID'), 33, NULL, 'J', 4)
/
INSERT INTO gey_mineral (code, name, formel, art, hier, ort, text, farbe_hex, reihenfolge) VALUES ('SKORODIT', 'Skorodit', 'FeAsO₄ · 2 H₂O', 'Eisenarsenat', 'N', 'Nicht in diesen Becken: Porcelain Basin und Gap Spring in Norris', 'Wo besonders viel Arsen im Wasser ist, bildet sich statt des amorphen Oxids Skorodit, ein Eisenarsenat. In Norris ist Arsen im Wasser ein bis zwei Größenordnungen höher als in anderen Quellen.', '#78A08A', 5)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'SKORODIT'), 26, 1.0000, 'N', 1)
