/
INSERT INTO gey_mineral (code, name, formel, art, hier, ort, text, farbe_hex, reihenfolge) VALUES ('ALUNIT', 'Alunit', 'KAl₃(SO₄)₂(OH)₆', 'Sulfat aus saurer Umwandlung', 'N', 'Nicht in diesen Becken: saure Dampfzonen und Schlammtöpfe', 'Saurer Dampf zersetzt das Gestein: Aus dem Rhyolith werden Opal, Kaolinit, Alunit und Pyrit. Das bleicht und färbt die Hänge, etwa im Grand Canyon of the Yellowstone.', '#DED6E2', 6)
/
INSERT INTO gey_mineral_element (mineral_id, atomic_number, anzahl, spur, reihenfolge) VALUES ((SELECT mineral_id FROM gey_mineral WHERE code = 'ALUNIT'), 19, 1.0000, 'N', 1)
